\documentclass{article}
\usepackage[T1]{fontenc}
\usepackage[utf8]{inputenc}
\usepackage[spanish]{babel}
\usepackage{amssymb}
\usepackage{amsmath}

\title{Cuaderno matemático}
\author{Estudiante}
\date{\today}

\begin{document}
\maketitle

\textbf{Enunciado.} Simplifica $(x+1)^2$.

Desarrollamos paso a paso:
\begin{align*}(x+1)^2&=x^2+2x+1\\&=x(x+2)+1\end{align*}

La respuesta es $\boxed{x^2+2x+1}$.
\end{document}
